function overlap(a,b){const A=a?.dashas?.periods||[],B=b?.dashas?.periods||[],out=[];for(const x of A)for(const y of B){const s=x.start>y.start?x.start:y.start,e=x.end<y.end?x.end:y.end;if(s&&e&&s<=e)out.push(`${x.lord||x.name} / ${y.lord||y.name}: ${s} → ${e}`)}return out.slice(0,6)}
