 if(lp){const d=dignity(lord7,lp.longitude);if(/Own|Exalted|சொந்த|உச்ச/.test(d)){protection++;reasons.push(T('7th lord has strong dignity','7-ஆம் அதிபதிக்கு நல்ல ராசி பலம் உள்ளது'));}}
